import os
from typing import Optional, Tuple

from azure.ai.inference import ChatCompletionsClient
from azure.core.credentials import AzureKeyCredential
from azure.core.exceptions import HttpResponseError


class AzureAIInferenceResolver:
    def __init__(
        self,
        endpoint: Optional[str] = None,
        api_key: Optional[str] = None,
        deployment_name: Optional[str] = None,
        model_name: Optional[str] = None,
        api_version: Optional[str] = None,
    ) -> None:
        self.endpoint = (endpoint or os.environ.get("AZURE_INFERENCE_ENDPOINT", "")).rstrip("/")
        self.api_key = api_key or os.environ.get("AZURE_INFERENCE_API_KEY", "")
        self.deployment_name = deployment_name or os.environ.get("AZURE_INFERENCE_DEPLOYMENT")
        self.model_name = model_name or os.environ.get("AZURE_INFERENCE_MODEL")
        self.api_version = api_version or os.environ.get("AZURE_INFERENCE_API_VERSION")

        if not self.endpoint:
            raise ValueError("Missing Azure AI Inference endpoint. Set AZURE_INFERENCE_ENDPOINT.")
        if not self.api_key:
            raise ValueError("Missing Azure AI Inference API key. Set AZURE_INFERENCE_API_KEY.")
        if not (self.deployment_name or self.model_name):
            raise ValueError(
                "Provide either deployment_name or model_name, or set AZURE_INFERENCE_DEPLOYMENT / AZURE_INFERENCE_MODEL."
            )

    def _client(self) -> ChatCompletionsClient:
        kwargs = {}
        if self.api_version:
            kwargs["api_version"] = self.api_version
        return ChatCompletionsClient(
            endpoint=self.endpoint,
            credential=AzureKeyCredential(self.api_key),
            **kwargs,
        )

    def resolve_target(self) -> Tuple[str, str]:
        client = self._client()

        if self.deployment_name:
            return "deployment", self.deployment_name

        try:
            info = client.get_model_info()
        except HttpResponseError as e:
            raise RuntimeError(
                f"Could not resolve model info from Azure AI Inference endpoint {self.endpoint}: {e}"
            ) from e

        resolved_model = getattr(info, "model_name", None) or getattr(info, "name", None)
        if not resolved_model:
            raise RuntimeError(
                "Azure AI Inference endpoint did not return a resolvable model identifier."
            )

        if self.model_name and self.model_name != resolved_model:
            raise RuntimeError(
                f"Requested model '{self.model_name}' does not match endpoint-resolved model '{resolved_model}'."
            )

        return "model", resolved_model

    def invoke(self, prompt: str, max_tokens: int = 256) -> str:
        client = self._client()
        target_type, target_value = self.resolve_target()

        request_kwargs = {
            "messages": [{"role": "user", "content": prompt}],
            "max_tokens": max_tokens,
        }

        if target_type == "model":
            request_kwargs["model"] = target_value

        try:
            response = client.complete(**request_kwargs)
        except HttpResponseError as e:
            raise RuntimeError(
                f"Azure AI Inference invocation failed for {target_type} '{target_value}': {e}"
            ) from e

        choices = getattr(response, "choices", None) or []
        if not choices:
            return ""

        message = getattr(choices[0], "message", None)
        if message is None:
            return ""

        content = getattr(message, "content", None)
        if isinstance(content, str):
            return content

        if isinstance(content, list):
            parts = []
            for item in content:
                text = getattr(item, "text", None)
                if text:
                    parts.append(text)
            return "".join(parts)

        return ""


def invoke_with_resolved_azure_inference_target(prompt: str) -> str:
    resolver = AzureAIInferenceResolver()
    return resolver.invoke(prompt)
